kubectl run node-access --rm -i --tty --restart=Never --image=busybox --overrides='
{
  "spec": {
    "hostPID": true,
    "hostNetwork": true,
    "containers": [
      {
        "name": "node-access",
        "image": "busybox",
        "command": ["chroot", "/host", "sh", "-c", "which kubeadm crictl containerd; kubeadm version; cat /etc/os-release"],
        "securityContext": {
          "privileged": true
