kubectl run prep-upgrade --rm -i --restart=Never --image=busybox --overrides='
{
  "spec": {
    "hostPID": true,
    "hostNetwork": true,
    "containers": [
      {
        "name": "prep-upgrade",
        "image": "busybox",
        "command": ["chroot", "/host", "sh", "-c", "
          curl -sSL -o /root/kubeadm https://dl.k8s.io/release/v1.31.0/bin/linux/amd64/kubeadm
          curl -sSL -o /root/kubelet https://dl.k8s.io/release/v1.31.0/bin/linux/amd64/kubelet
          curl -sSL -o /root/kubectl https://dl.k8s.io/release/v1.31.0/bin/linux/amd64/kubectl
          chmod +x /root/kubeadm /root/kubelet /root/kubectl
          cp /root/kubeadm /usr/bin/kubeadm
          /usr/bin/kubeadm version
          /root/kubelet --version
          /root/kubectl version --client
        "],
        "securityContext": {
          "privileged": true
        },
        "volumeMounts": [
          {
            "name": "host-root",
            "mountPath": "/host"
          }
        ]
      }
    ],
    "volumes": [
      {
        "name": "host-root",
        "hostPath": {
          "path": "/"
        }
      }
    ]
  }
}
'

