        "command": ["chroot", "/host", "sh", "-c", "cat <<'\''EOF'\'' > /root/upgrade-cluster.sh\n#!/bin/bash\nset -ex\nexec > /root/upgrade.log 2>&1\necho \"Starting kubeadm upgrade apply...\"\nkubeadm upgrade apply -y v1.31.0\necho \"Updating kubelet and kubectl binaries...\"\ncp /root/kubelet /usr/bin/kubelet\ncp /root/kubectl /usr/bin/kubectl\nsystemctl daemon-reload\nsystemctl restart kubelet\necho \"UPGRADE_FINISHED_SUCCESSFULLY\"\nEOF\nchmod +x /root/upgrade-cluster.sh\nsystemd-run --unit=cluster-upgrade /root/upgrade-cluster.sh\n"],
        "securityContext": {
          "privileged": true
        },
        "volumeMounts": [
          {
            "name": "host-root",
            "mountPath": "/host"
